using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(200)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough into a circle\n3. Spread crushed tomatoes over dough\n4. Tear mozzarella and distribute evenly\n5. Bake for 10-12 minutes\n6. Top with fresh basil and drizzle with olive oil",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook pasta in salted water\n2. Crisp guanciale in a pan\n3. Whisk eggs with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately with extra pecorino",
            AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or broil chicken until charred\n3. Sauté garlic and ginger in oil\n4. Add spices and cook until fragrant\n5. Add tomatoes and simmer 15 minutes\n6. Stir in cream and cooked chicken\n7. Simmer 10 more minutes",
            AverageRating = 4.6, RatingCount = 15
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs",
            Steps = "1. Soak rice noodles in warm water\n2. Mix tamarind paste, fish sauce, and sugar for sauce\n3. Stir-fry tofu until golden\n4. Push aside, scramble eggs\n5. Add drained noodles and sauce\n6. Toss with bean sprouts and green onions\n7. Serve with peanuts and lime wedges",
            AverageRating = 4.3, RatingCount = 8
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomatoes\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water, simmer\n3. Warm tortillas in a dry pan\n4. Assemble tacos with beef and toppings\n5. Serve with salsa and sour cream",
            AverageRating = 4.2, RatingCount = 10
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F\n2. Melt chocolate and butter together\n3. Whisk eggs and sugar until thick\n4. Fold in chocolate mixture\n5. Add flour and vanilla\n6. Pour into greased ramekins\n7. Bake 12-14 minutes until edges are set\n8. Invert onto plates and serve immediately",
            AverageRating = 4.9, RatingCount = 25
        }
    };

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = totalStars / recipe.RatingCount;
    }
}

